-- Kadara Fangbreaker (443156) -- Bloodmoon Keep missions.
-- Generated by sof_content/gen_loping_missions.py -- do not hand-edit.
local MISSIONS = {301205, 301206}
local REQUIRES = {[301205] = 301200, [301206] = 301201}
local DEFS = {
	[301205] = { name = "Moonfang", max = 12 },
	[301206] = { name = "The Broodmother", max = 12 },
}

local BUCKET = "sof.loping.missions"
local BUCKET_TOTAL = 7

function event_task_complete(e)
	for _, tid in ipairs(MISSIONS) do
		if e.task_id == tid then
			local n = tonumber(e.other:GetBucket(BUCKET)) or 0
			if n < BUCKET_TOTAL then
				e.other:SetBucket(BUCKET, tostring(n + 1))
			end
			return
		end
	end
end

function event_say(e)
	if e.message:findi("hail") then
		e.self:Say("Hail, " .. e.other:GetCleanName() .. ". The Bloodmoon will not fall on its own. Ask me about a [mission].")
	elseif e.message:findi("mission") or e.message:findi("task") or e.message:findi("work") then
		local available = {}
		for _, tid in ipairs(MISSIONS) do
			local required = REQUIRES[tid]
			if required == nil or e.other:IsTaskCompleted(required) then
				available[#available + 1] = tid
			end
		end
		e.self:Say("These are the strikes I can lead, " .. e.other:GetCleanName() .. ".")
		eq.task_selector(available)
	elseif e.message:findi("enter") or e.message:findi("zone in") or e.message:findi("go in") then
		local active = nil
		for _, tid in ipairs(MISSIONS) do
			if e.other:IsTaskActive(tid) then
				active = tid
				break
			end
		end
		if active == nil then
			e.self:Say("You hold no mission of mine to lead you in.")
			return
		end
		local current = e.other:GetExpedition()
		if current.valid then
			e.other:MovePCDynamicZone(current:GetZoneID())
			return
		end
		local d = DEFS[active]
		local dz = e.other:CreateExpedition({
			expedition = { name = d.name, min_players = 1, max_players = d.max },
			instance = { zone = "bloodmoon", version = 0, duration = eq.seconds("6h") },
			compass = { zone = "lopingplains", x = -3157.0, y = -1361.0, z = 702.875 },
			safereturn = { zone = "lopingplains", x = -3157.0, y = -1361.0, z = 702.875, h = 0 },
			zonein = { x = 0, y = 0, z = 0, h = 0 },
			switchid = 0,
		})
		if dz.valid then
			e.self:Say("Then to Bloodmoon. Hold fast.")
			e.other:MovePCDynamicZone(dz:GetZoneID())
		else
			e.self:Say("The way is blocked -- try again shortly.")
		end
	end
end

function event_trade(e)
	local item_lib = require("items")
	item_lib.return_items(e.self, e.other, e.trade)
end
